const h=helpers(),member=require(path.resolve('miniapp/cloudfunctions/memberAccess/service')),sched=require(path.resolve('miniapp/cloudfunctions/memberAccess/schedule-service'));
const hash=x=>crypto.createHash('sha256').update(x).digest('hex'),uid=x=>'u_'+hash(member.APPID+':'+x).slice(0,40),manager=uid('r2-manager'),worker=uid('r2-worker');
function setup(){const db=h.createMockDb({users:{},app_admins:{}});h.seedProject(db,'p-review',manager,worker,'水电');for(const [o,u]of [['r2-manager',manager],['r2-worker',worker]])db.collection('users').add({data:{_id:u,openid:o,status:'active'}});const s=sched.createScheduleService(db),full=member.createService(db);const form={stage:'水电隐蔽工程',trade:'水电',workerUserId:worker,startDate:'2026-10-02',endDate:'2026-10-02',expectedDate:'2026-10-02',restDays:[],content:'本地合成测试内容'};return{db,s,form,call:(action,data={})=>full.execute({action,projectId:'p-review',...data},{APPID:member.APPID,OPENID:'r2-manager'})};}
async function capture(name,fn){try{results.push({name,...await fn()});}catch(e){results.push({name,replayError:e.message,code:e.code});}}
const tick=()=>new Promise(r=>setImmediate(r));
function page(name,client){const filename=path.resolve('miniapp/miniprogram/pages/'+name+'/'+name+'.js'),realRequire=createRequire(filename);let definition;const events=[],modals=[];vm.runInNewContext(fs.readFileSync(filename,'utf8'),{require:n=>n.includes('/schedule-client')?client:n.includes('/ui')?{fail:e=>events.push({error:e.message}),go:url=>events.push({url}),context:realRequire(n).context}:n.includes('/store')?{read:()=>require(path.resolve('miniapp/miniprogram/utils/seed')).createSeed('2026-10-02')}:realRequire(n),Page:d=>definition=d,wx:{showModal:o=>modals.push(o),showToast:o=>events.push(o),navigateBack:()=>events.push('back')},Date,Math});return{...definition,data:JSON.parse(JSON.stringify(definition.data)),setData(v){for(const[k,value]of Object.entries(v)){const parts=k.split('.');let obj=this.data;for(const part of parts.slice(0,-1)){obj[part]||={};obj=obj[part];}obj[parts.at(-1)]=value;}},events,modals};}
function bridge(x){return{checkEntry:()=>({allowed:true}),getScheduleContext:()=>x.call('getScheduleContext'),listSchedules:(_p,f)=>x.call('listSchedules',f),getSchedule:(_p,scheduleId)=>x.call('getSchedule',{scheduleId}),listScheduleRevisions:(_p,scheduleId)=>x.call('listScheduleRevisions',{scheduleId})};}(async()=>{
await capture('guard_101_cancel100_blocks_real_remove',async()=>{const x=setup();for(let i=0;i<101;i++)await x.db.collection('schedules').add({data:{...x.form,_id:'s-'+i,projectId:'p-review',version:1,status:'active',createdAt:'2026-10-03T00:00:00Z'}});for(let i=0;i<100;i++)await x.call('cancelSchedule',{scheduleId:'s-'+i,expectedVersion:1,requestId:'c-'+i,reason:'test'});try{await x.call('removeMember',{userId:worker});return{passed:false};}catch(e){return{passed:e.code==='WORKER_HAS_ACTIVE_SCHEDULES',code:e.code};}});
await capture('history_limit_one_reaches_update',async()=>{const x=setup(),r=await x.call('createSchedule',{requestId:'a',form:x.form});await x.call('updateSchedule',{scheduleId:r.scheduleId,expectedVersion:1,requestId:'b',form:{...x.form,content:'new'},reason:'test'});const a=await x.call('listScheduleRevisions',{scheduleId:r.scheduleId,limit:1});const b=await x.call('listScheduleRevisions',{scheduleId:r.scheduleId,limit:1,cursor:a.pagination.nextCursor});return{passed:a.revisions.length===1&&b.revisions.length===1,first:a.pagination,second:b.pagination};});
await capture('context_all_102_workers',async()=>{const x=setup();for(let i=0;i<101;i++)await x.db.collection('project_members').add({data:{_id:'worker-'+i,projectId:'p-review',userId:'worker-'+i,roles:['师傅'],trades:['水电'],status:'active'}});const ctx=await x.call('getScheduleContext');return{passed:ctx.workers.length===102,count:ctx.workers.length};});
await capture('cancelled_schedule_date_filter',async()=>{const x=setup(),r=await x.call('createSchedule',{requestId:'a',form:x.form});await x.call('cancelSchedule',{scheduleId:r.scheduleId,expectedVersion:1,requestId:'b',reason:'test'});const dated=await x.call('listSchedules',{date:x.form.startDate,status:'cancelled'});return{passed:dated.schedules.length===1,count:dated.schedules.length};});
function fill(p){Object.assign(p.data.form,{workerId:worker,trade:'水电',stage:'水电隐蔽工程',start:'2026-10-02',end:'2026-10-02',expected:'2026-10-02',content:'first',restDays:[]});}
await capture('H1_acknowledge_without_read_allows_second_create',async()=>{const x=setup(),c=bridge(x),requests=[];let first=true;c.createSchedule=async(_p,form,opts)=>{requests.push(opts.requestId);const r=await x.call('createSchedule',{requestId:opts.requestId,form,expectedConfirmed:opts.expectedConfirmed});if(first){first=false;throw Error('网络响应丢失');}return r;};const p=page('schedule',c);p.onLoad({projectId:'p-review'});await tick();fill(p);p.save();await tick();const firstState=p.data.pendingRequest.state;p.discardPending();for(const f of ['start','end','expected'])p.input({currentTarget:{dataset:{field:f}},detail:{value:'2026-10-03'}});p.save();await tick();const items=await x.call('listSchedules');return{reproduced:items.schedules.length===2,firstState,createdCount:items.schedules.length,requestIdChanged:requests[0]!==requests[1]};});
await capture('H1_malformed_response_after_commit_marked_failed',async()=>{const x=setup(),c=bridge(x);c.createSchedule=async(_p,form,opts)=>{await x.call('createSchedule',{requestId:opts.requestId,form});throw Error('云端响应异常，请稍后重试。');};const p=page('schedule',c);p.onLoad({projectId:'p-review'});await tick();fill(p);p.save();await tick();return{reproduced:p.data.pendingRequest.state==='failed',state:p.data.pendingRequest.state,serverCreated:(await x.call('listSchedules')).schedules.length};});
await capture('H2_correcting_business_error_cannot_save',async()=>{const x=setup(),c=bridge(x);let calls=0;c.createSchedule=async(_p,form,opts)=>{calls++;return x.call('createSchedule',{requestId:opts.requestId,form});};const p=page('schedule',c);p.onLoad({projectId:'p-review'});await tick();fill(p);p.input({currentTarget:{dataset:{field:'content'}},detail:{value:''}});p.save();await tick();const firstError=p.data.error;p.input({currentTarget:{dataset:{field:'content'}},detail:{value:'corrected'}});p.save();await tick();return{reproduced:!!firstError&&calls===1,firstError,remainingError:p.data.error,requestCount:calls,correctedContent:p.data.form.content};});
await capture('existing_zero_guard_still_allows_remove_with_active_schedule',async()=>{const x=setup();await x.call('createSchedule',{requestId:'a',form:x.form});await x.db.collection('member_task_guard').doc('p-review:'+worker).update({data:{activeScheduleCount:0}});await x.call('removeMember',{userId:worker});const m=(await x.db.collection('project_members').doc(h.memberId('p-review',worker)).get()).data;const s=await x.db.collection('schedules').where({projectId:'p-review',status:'active'}).get();return{reproduced:m.status==='left'&&s.data.length===1,memberStatus:m.status,activeSchedules:s.data.length,fixture:'人为注入历史不一致计数，非正常顺序调用自行产生'};});const out={recordedAt:new Date().toISOString(),type:'local-only-G1-G6-review',results,cloudRequests:0};fs.writeFileSync(path.join(process.env.TEMP,'yf-g-review-replays.json'),JSON.stringify(out,null,2));console.log(JSON.stringify(out,null,2));
})().catch(e=>{console.error(e);process.exitCode=1});

